<?php

declare(strict_types=1);

require_once dirname(__DIR__) . '/includes/bootstrap.php';
require_once dirname(__DIR__) . '/includes/admin-auth.php';

$summary = ['orders' => 0, 'revenue' => 0, 'products' => 0, 'inventory_units' => 0, 'customers' => 0, 'returns' => 0, 'refunds' => 0];
$daily = [];
$topProducts = [];
$lowStock = [];
$error = '';
try {
    $connection = database_connection();
    admin_require($connection, 'reports.view');
    $summary['orders'] = (int) $connection->query("SELECT COUNT(*) FROM orders WHERE status NOT IN ('cancelled')")->fetchColumn();
    $summary['revenue'] = (float) $connection->query("SELECT COALESCE(SUM(amount), 0) FROM payments WHERE status IN ('paid', 'partially_refunded')")->fetchColumn();
    $summary['products'] = (int) $connection->query("SELECT COUNT(*) FROM products WHERE status <> 'archived'")->fetchColumn();
    $summary['inventory_units'] = (int) $connection->query('SELECT COALESCE(SUM(quantity_on_hand - quantity_reserved), 0) FROM inventory')->fetchColumn();
    $summary['customers'] = (int) $connection->query("SELECT COUNT(*) FROM users WHERE status = 'active'")->fetchColumn();
    $summary['returns'] = (int) $connection->query("SELECT COUNT(*) FROM returns WHERE status NOT IN ('cancelled', 'rejected', 'completed')")->fetchColumn();
    $summary['refunds'] = (float) $connection->query("SELECT COALESCE(SUM(amount), 0) FROM refunds WHERE status = 'processed'")->fetchColumn();
    $daily = $connection->query("SELECT DATE(o.created_at) AS day, COUNT(DISTINCT o.id) AS orders, COALESCE(SUM(CASE WHEN p.status IN ('paid', 'partially_refunded') THEN p.amount ELSE 0 END), 0) AS revenue FROM orders o LEFT JOIN payments p ON p.order_id = o.id WHERE o.created_at >= UTC_DATE() - INTERVAL 29 DAY AND o.status <> 'cancelled' GROUP BY DATE(o.created_at) ORDER BY day DESC")->fetchAll();
    $topProducts = $connection->query("SELECT oi.product_name, oi.sku, SUM(oi.quantity) AS units, SUM(oi.line_total) AS sales FROM order_items oi INNER JOIN orders o ON o.id = oi.order_id WHERE o.status NOT IN ('cancelled', 'returned') GROUP BY oi.product_id, oi.product_name, oi.sku ORDER BY units DESC, sales DESC LIMIT 10")->fetchAll();
    $lowStock = $connection->query('SELECT products.name, product_variants.sku, inventory.quantity_on_hand, inventory.quantity_reserved, inventory.reorder_level FROM inventory INNER JOIN product_variants ON product_variants.id = inventory.variant_id INNER JOIN products ON products.id = product_variants.product_id WHERE inventory.quantity_on_hand - inventory.quantity_reserved <= inventory.reorder_level ORDER BY inventory.quantity_on_hand - inventory.quantity_reserved ASC, products.name LIMIT 20')->fetchAll();
} catch (Throwable $exception) { error_log($exception->getMessage()); $error = 'Reports are temporarily unavailable.'; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reports | Admin</title><link rel="stylesheet" href="<?= escape_html(asset_url('css/site.css')) ?>"></head><body class="admin-page"><aside class="admin-sidebar"><a class="admin-brand" href="<?= escape_html(base_url('admin/')) ?>">SC <span>Admin</span></a><nav aria-label="Admin navigation"><a href="<?= escape_html(base_url('admin/')) ?>">Overview</a><a class="is-active" href="<?= escape_html(base_url('admin/reports.php')) ?>">Reports</a><a href="<?= escape_html(base_url('admin/module.php?name=orders')) ?>">Orders</a><a href="<?= escape_html(base_url('admin/module.php?name=inventory')) ?>">Inventory</a><a href="<?= escape_html(base_url('admin/module.php?name=returns')) ?>">Returns</a><a href="<?= escape_html(base_url('admin/module.php?name=refunds')) ?>">Refunds</a></nav></aside><main class="admin-main"><header class="admin-topbar"><div><p class="eyebrow">Verified database reporting</p><h1>Commerce reports</h1></div><a class="button button--outline" href="<?= escape_html(base_url('admin/')) ?>">Overview</a></header><?php if ($error !== ''): ?><div class="alert alert--soft" role="alert"><?= escape_html($error) ?></div><?php endif; ?><section class="admin-metrics" aria-label="Commerce report summary"><?php foreach ([['orders', 'Orders', number_format($summary['orders'])], ['revenue', 'Paid revenue', '₹ ' . number_format($summary['revenue'], 2)], ['products', 'Active products', number_format($summary['products'])], ['inventory_units', 'Available units', number_format($summary['inventory_units'])], ['customers', 'Active customers', number_format($summary['customers'])], ['returns', 'Open returns', number_format($summary['returns'])], ['refunds', 'Processed refunds', '₹ ' . number_format($summary['refunds'], 2)]] as $card): ?><article class="admin-metric"><span><?= escape_html($card[1]) ?></span><strong><?= escape_html($card[2]) ?></strong></article><?php endforeach; ?></section><section class="admin-panel"><div class="section__header"><div><p class="eyebrow">Last 30 days</p><h2>Sales overview</h2></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Date</th><th>Orders</th><th>Paid revenue</th></tr></thead><tbody><?php foreach ($daily as $row): ?><tr><td><?= escape_html((string) $row['day']) ?></td><td><?= escape_html((string) $row['orders']) ?></td><td>₹ <?= escape_html(number_format((float) $row['revenue'], 2)) ?></td></tr><?php endforeach; ?><?php if ($daily === []): ?><tr><td colspan="3">No recorded orders in this period.</td></tr><?php endif; ?></tbody></table></div></section><section class="admin-panel"><div class="section__header"><div><p class="eyebrow">Catalogue performance</p><h2>Top products</h2></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>SKU</th><th>Units</th><th>Sales</th></tr></thead><tbody><?php foreach ($topProducts as $row): ?><tr><td><?= escape_html((string) $row['product_name']) ?></td><td><?= escape_html((string) $row['sku']) ?></td><td><?= escape_html((string) $row['units']) ?></td><td>₹ <?= escape_html(number_format((float) $row['sales'], 2)) ?></td></tr><?php endforeach; ?><?php if ($topProducts === []): ?><tr><td colspan="4">No product sales recorded.</td></tr><?php endif; ?></tbody></table></div></section><section class="admin-panel"><div class="section__header"><div><p class="eyebrow">Inventory health</p><h2>Low-stock products</h2></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>SKU</th><th>Available</th><th>Reorder level</th></tr></thead><tbody><?php foreach ($lowStock as $row): ?><tr><td><?= escape_html((string) $row['name']) ?></td><td><?= escape_html((string) $row['sku']) ?></td><td><?= escape_html((string) ((int) $row['quantity_on_hand'] - (int) $row['quantity_reserved'])) ?></td><td><?= escape_html((string) $row['reorder_level']) ?></td></tr><?php endforeach; ?><?php if ($lowStock === []): ?><tr><td colspan="4">No low-stock products.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
